import income from '@/component/income.vue';
import expenditure from '@/component/expenditure.vue';
import dateTimePicker from '@/component/datetime-picker.vue';
import utils from '@/common/utils.js'

export default {
	data() {
		return {
			currentTab: 0,

			tabList: [{ id: 0, name: '支出' }, { id: 1, name: '收入' }],

			goodsObj: {}, // 选中的支出/收入

			money: '', //
			payTime: '', //
			remark: '' //
		};
	},

	onLoad() {console.log(111)},

	methods: {
		// 点击tab
		changeTab(id) {
			this.currentTab = id;
		},

		// 滑动swiper
		slideSwiper(e) {
			this.currentTab = e.mp.detail.current;
		},

		// 选择收入类型
		chooseIncome(data) {
			console.log(data);
			this.goodsObj = data;
		},

		// 选择支出类型
		chooseExpenditure(data) {
			this.goodsObj = data;
		},

		// 打开时间picker
		openDatetimePicker() {
			this.$refs.myPicker.show();
		},

		// 关闭时间picker
		closeDatetimePicker() {
			this.$refs.myPicker.hide();
		},

		// 监听时间icker选择
		dateTimeSubmit(e) {
			// 当前时间
			const nowTime = new Date().getTime();
			// 选中时间
			const pickerTime = `${e.year}-${e.month}-${e.day} ${e.hour}:${e.minute}`;
			// 不能大于当前时间
			if( new Date(pickerTime).getTime() > nowTime ){
				this.$common.toast('选中时间不能大于当前时间');
				return
			}
			this.payTime = pickerTime;
		},

		// 提交表单
		submitFormEvt() {
			const formType = this.tabList[this.currentTab],
				{ id } = this.goodsObj,
				money = this.money,
				payTime = this.payTime,
				remark = this.remark;

			if (!id && id !== 0) {
				this.$common.toast('请选择收支类型');
				return;
			}
			if(!utils.checkMoney(money)){
				this.$common.toast('请输入金额，如有小数保留2位');
				return
			}
			if (!payTime) {
				this.$common.toast('请选择时间');
				return;
			}
			if (!remark) {
				this.$common.toast('请输入备注');
				return;
			}

			/* 1=>支出 2=>收入 */
			const params = {
				type: formType.id + 1,
				money,
				payTime,
				goodsId: id,
				remark
			};
			this.$api({
				url: '/user/bookkeeping',
				data: params
			})
				.then( (res) => {
					if(res){
						let userInfo = this.$store.state.userInfo;
						userInfo.balance = res.balance;

						this.$common.toast('提交成功');
						// 通知首页刷新订单
						this.$store.commit('SETBOOKKEEPING', true);
						
						// 将最新余额存入本地userInfo和store
						this.$store.commit('SETUSERINFO', userInfo);
						this.$common.setStorage('userInfo', userInfo);
						
						uni.navigateBack({
							delta: 1
						});
					}
				})
				.catch(e => {
					this.$common.toast(e.msg);
				})
				.finally();
		}
	},

	components: {
		income,
		expenditure,
		dateTimePicker
	}
};
